    FwHttpApi.prototype.agregarFiltroARequestOptionsArgs = function (opciones, campos) {
        var _this = this;
        if (campos && campos.length > 0) {
            var camposSerializados_1 = new Array();
            campos.forEach(function (campo) {
                if ((campo.valor.listaValores && campo.valor.listaValores.length > 0) ||
                    !FwTipos.esNull(campo.valor.valor) ||
                    !FwTipos.esNull(campo.valor.valorDesde) ||
                    !FwTipos.esNull(campo.valor.valorHasta)) {
                    camposSerializados_1.push(_this.obtenerCampoAdaptado(campo));
                }
            });
            var filtroObj_1 = {};
            camposSerializados_1.forEach(function (x) {
                if (x.valor) {
                    var propNombre = x.id[0].toUpperCase() + x.id.substr(1);
                    if (x.valor.valorSelector &&
                        !x.valor.valorSelector[x.id] &&
                        Object.keys(x.valor.valorSelector)) {
                        filtroObj_1[propNombre] = x.valor.valorSelector[Object.keys(x.valor.valorSelector)[0]];
                    }
                    else {
                        if (propNombre.toLowerCase().startsWith("desde")) {
                            filtroObj_1[propNombre] = x.valor.valorDesde;
                        }
                        else if (propNombre.toLowerCase().startsWith("hasta")) {
                            filtroObj_1[propNombre] = x.valor.valorHasta;
                        }
                        else if (x.operador == FwOperadoresFiltro.Entre) {
                            filtroObj_1["Desde" + propNombre] = x.valor.valorDesde;
                            filtroObj_1["Hasta" + propNombre] = x.valor.valorHasta;
                        }
                        else {
                            filtroObj_1[propNombre] = !FwTipos.esNull(x.valor.valor) ? x.valor.valor : (x.valor.valorDesde || x.valor.valorHasta || x.valor.listaValores || x.valor.valorSelector[x.id]);
                        }
                    }
                }
            });
            opciones.headers = opciones.headers.append("praxys-filtro", JSON.stringify(filtroObj_1));
        }
    };
    FwHttpApi.prototype.obtenerCampoAdaptado = function (campo) {
        var campoFinal = {};
        if (FwTipos.esDate(campo.valor.valor) || FwTipos.esDate(campo.valor.valorHasta) || FwTipos.esDate(campo.valor.valorDesde)) {
            var valorDesde = new Date(campo.valor.valor);
            var valorHasta = new Date(campo.valor.valor);
            switch (campo.configuracionCampo.operador) {
                case FwOperadoresFiltro.Igual:
                    valorDesde.setHours(0);
                    valorDesde.setSeconds(0);
                    valorDesde.setMinutes(0);
                    valorDesde.setMilliseconds(0);
                    valorHasta.setHours(23);
                    valorHasta.setSeconds(59);
                    valorHasta.setMinutes(59);
                    valorHasta.setMilliseconds(999);
                    return {
                        id: campo.configuracionCampo.id,
                        operador: FwOperadoresFiltro.Entre,
                        valor: {
                            valor: null,
                            valorDesde: valorDesde,
                            valorHasta: valorHasta
                        }
                    };
                case FwOperadoresFiltro.Entre:
                    if (campo.valor.valorDesde) {
                        valorDesde.setHours(0);
                        valorDesde.setSeconds(0);
                        valorDesde.setMinutes(0);
                        valorDesde.setMilliseconds(0);
                    }
                    if (campo.valor.valorHasta) {
                        valorHasta.setHours(23);
                        valorHasta.setSeconds(59);
                        valorHasta.setMinutes(59);
                        valorHasta.setMilliseconds(999);
                    }
                    campoFinal = campo;
                    break;
                case FwOperadoresFiltro.Mayor:
                    campo.valor.valor.setHours(0);
                    campo.valor.valor.setSeconds(0);
                    campo.valor.valor.setMinutes(0);
                    campo.valor.valor.setMilliseconds(0);
                    campoFinal = campo;
                    break;
                case FwOperadoresFiltro.MayorIgual:
                    campo.valor.valor.setHours(0);
                    campo.valor.valor.setSeconds(0);
                    campo.valor.valor.setMinutes(0);
                    campo.valor.valor.setMilliseconds(0);
                    campoFinal = campo;
                    break;
                case FwOperadoresFiltro.Menor:
                    campo.valor.valor.setHours(23);
                    campo.valor.valor.setSeconds(59);
                    campo.valor.valor.setMinutes(59);
                    campo.valor.valor.setMilliseconds(999);
                    campoFinal = campo;
                    break;
                case FwOperadoresFiltro.MenorIgual:
                    campo.valor.valor.setHours(23);
                    campo.valor.valor.setSeconds(59);
                    campo.valor.valor.setMinutes(59);
                    campo.valor.valor.setMilliseconds(999);
                    campoFinal = campo;
                    break;
                default:
                    campoFinal = campo;
                    break;
            }
        }
        else {
            if (campo.configuracionCampo.constructor.name === "FwConfiguracionCampoSelector") {
                campoFinal.configuracionCampo = campo.configuracionCampo;
                campoFinal.valor = { valorSelector: campo.configuracionCampo['valorActual'] ? campo.configuracionCampo['valorActual'] : {} };
            }
            else {
                campoFinal = campo;
            }
        }
        return {
            id: campoFinal.configuracionCampo.id,
            operador: campoFinal.configuracionCampo.operador,
            valor: campoFinal.valor
        };
    };
