    SolicitudAutorizacionComp.prototype.iniciarFormulario = function (afiliadoSeleccionado) {
        var _this = this;
        var controlReceptorFoco;
        if (afiliadoSeleccionado) {
            controlReceptorFoco = "numeroReceta";
        }
        else if (this.esMesaAyuda) {
            controlReceptorFoco = "farmacia";
        }
        else if (this.esFarmacia) {
            this.itemActual.idFarmacia = this.idFarmacia;
            controlReceptorFoco = "convenioPlan";
        }
        var t = setTimeout(function () {
            if (_this.formulario) {
                _this.formulario.darFoco(controlReceptorFoco);
            }
            clearTimeout(t);
        });
    };
    SolicitudAutorizacionComp.prototype.restablecerFormulario = function (mantenerAfiliado) {
        var _this = this;
        var datos;
        if (mantenerAfiliado) {
            datos = {
                idFarmacia: this.itemActual.idFarmacia,
                idConvenio: this.itemActual.idConvenio,
                idPlan: this.itemActual.idPlan,
                numeroAfiliado: this.itemActual.numeroAfiliado,
            };
        }
        else {
            datos = {
                idFarmacia: this.itemActual.idFarmacia
            };
            this.estado.convenioPlan = null;
            this.estado.afiliado = null;
            this._selectorFarmacia = this.crearSelectorFarmacia();
            this.farmaciaDescripcion = "";
            this.convenioPlanDescripcion = "";
            this._selectorConvenioPlanPrincipal = this.crearSelectorConvenioPlanPrincipal();
            this._selectorAfiliado = this.crearSelectorAfiliado();
            this.numeroDocumento = "";
            this.estado.nombreAfiliado = "";
            this._lectorBanda = null;
            this._usandoSelectorAfiliado = false;
            this._selectorAfiliadoDeshabilitado = false;
            if (!this.panelComplementos.colapsado) {
                this.panelComplementos.colapsar();
            }
        }
        this.ordenComplemento = 0;
        this.estado.validacionReceta = null;
        this.estado.respuestaAutorizar = null;
        this.itemActual = new SolicitudAutorizar(datos);
        this.tablaRenglones.cargarArray(this.itemActual.renglones);
        this.tablaComplementos.cargarArray(this.itemActual.complementos);
        this.numeroReceta = "";
        this.mensajes = new Array();
        this.provinciaDescripcion = "";
        this.itemActual.idProvinciaMatricula = null;
        this._selectorProducto = this.crearSelectorProducto();
        this._selectorProvincia = this.crearSelectorProvincia();
        this._selectorMedicoMatricula = this.crearSelectorMedicoMatricula();
        this.nombreMedico = "";
        this.medicoEnRecetaElectronica = false;
        this.medicoSeleccionado = false;
        this.itemActual.esOdontologo = false;
        this.formulario.resetear(true);
        this._autorizacionImpresa = false;
        var ti = setTimeout(function () {
            _this.iniciarFormulario(mantenerAfiliado);
            _this.tipoMatricula = "N";
            clearTimeout(ti);
        });
    };
    SolicitudAutorizacionComp.prototype.configurarFormulario = function () {
        var _this = this;
        if (!this._seguridad.usuarioTieneRol("Farmacia")) {
            this.formulario.item("farmacia").validaciones = {
                requerido: true
            };
        }
        this.formulario.agregarControl("convenioPlan", {
            id: "convenioPlan",
            validaciones: {
                requerido: true
            }
        });
        //const hoy = this.contextoEjecucion.obtenerFechaHora();
        this.formulario.agregarControl("fechaPrescripcion", {
            id: "fechaPrescripcion",
            validaciones: {
                requerido: true /*,
                valorMaximo: hoy*/
            }
        });
        this.formulario.controlValidado.subscribe(function (control) {
            switch (control.id) {
                case "tipoMatricula":
                    if (_this.itemActual.tipoMatricula === "N") {
                        _this.itemActual.idProvinciaMatricula = "";
                        _this.provinciaDescripcion = "";
                    }
                    else {
                        if (_this.idFarmacia && _this.provinciaDescripcion === "" && !_this._obteniendoProvinciaFarmacia) {
                            _this._obteniendoProvinciaFarmacia = true;
                            _this.obtenerItemDesdeApi(_this._provinciasApi.consultarProvinciaPorFarmacia(_this.idFarmacia))
                                .subscribe(function (prov) {
                                _this._obteniendoProvinciaFarmacia = false;
                                if (!_this.itemActual.idProvinciaMatricula && !_this.provinciaDescripcion) {
                                    _this.itemActual.idProvinciaMatricula = prov.idProvincia;
                                    _this.provinciaDescripcion = prov.nombre;
                                }
                            });
                        }
                    }
            }
        });
        this.formulario
            .asignarValidacionesControl("numeroAfiliado", {
            longitudMaxima: 20
        })
            .asignarValidacionesControl("numeroReceta", {
            longitudMaxima: 30
        });
        this.formulario.agregarValidacion(function () {
            if (_this.estado.validacionReceta && _this.estado.validacionReceta.mensajes) {
                return _this.estado.validacionReceta.mensajes.map(function (o) { return new FwMensajeValidacion(o.descripcion, FwSeveridades.Aviso); });
            }
            return "";
        });
    };
